t.script:
                function volverARegistros() {
                    var lastPage = localStorage.getItem('lastRecordsPage');
                    var defaultPage = '/customer/records';

                    if (lastPage) {
                        // Intentar usar la última página guardada
                        navigateToPage(lastPage);
                    } else {
                        // Si no hay página guardada, intentar construir la URL
                        var urlParams = new URLSearchParams(window.location.search);
                        var customerId = urlParams.get('customer_id');
                        var userName = urlParams.get('user_name');
                        var phoneNumber = urlParams.get('phone_number');

                        if (customerId) {
                            var constructedUrl = defaultPage + '?customer_id=' + customerId;
                            if (userName) constructedUrl += '&user_name=' + encodeURIComponent(userName);
                            if (phoneNumber) constructedUrl += '&phone_number=' + encodeURIComponent(phoneNumber);
                            navigateToPage(constructedUrl);
                        } else {
                            // Si no hay customer_id, ir a la página por defecto
                            navigateToPage(defaultPage);
                        }
                    }
                }

                function navigateToPage(url) {
                    fetch(url, { method: 'HEAD' })
                        .then(function(response) {
                            if (response.ok) {
                                window.location.href = url;
                            } else {
                                handleError();
                            }
                        })
                        .catch(function(error) {
                            handleError();
                        });
                }

                function handleError() {
                    var errorMessage = "Lo sentimos, ha ocurrido un error al intentar volver a la página de registros. Por favor, intente una de las siguientes opciones:";
                    var options = [
                        { text: "Ir al inicio", action: function() { window.location.href = '/'; } },
                        { text: "Intentar de nuevo", action: function() { volverARegistros(); } },
                        { text: "Contactar soporte", action: function() { window.location.href = '/contact'; } }
                    ];
                    showErrorModal(errorMessage, options);
                }

                function showErrorModal(message, options) {
                    var modal = document.createElement('div');
                    modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;z-index:1000;';

                    var content = document.createElement('div');
                    content.style.cssText = 'background:white;padding:20px;border-radius:5px;max-width:80%;text-align:center;';
                    content.innerHTML = '
' + message + '';

                    options.forEach(function(option) {
                        var button = document.createElement('button');
                        button.textContent = option.text;
                        button.style.cssText = 'margin:5px;padding:10px;';
                        button.onclick = function() {
                            document.body.removeChild(modal);
                            option.action();
                        };
                        content.appendChild(button);
                    });

                    modal.appendChild(content);
                    document.body.appendChild(modal);
                }
